/* ---- status codes, enumerators and limits ---------------------------- */
/* Values are part of the ABI and never change. */
enum {
  FUSE_OK = 0,  /* success */
  FUSE_ERR_INVALID = -1,  /* malformed argument: null pointer, out-of-range value, bad handle, unparseable input */
  FUSE_ERR_NOTFOUND = -2,  /* well-formed lookup that found nothing: no such component or field */
  FUSE_ERR_STATE = -3,  /* valid call in the wrong state: no graph, already initialised, step already open */
  FUSE_ERR_RUNTIME = -4,  /* an exception was contained at the boundary or an operation failed; last_error has the reason */
  FUSE_ERR_UNSUPPORTED = -5,  /* the entry exists in this ABI but this build cannot perform it */
  FUSE_ERR_VERSION = -6,  /* struct_size smaller than the oldest layout this library knows, or larger than FUSE_ABI_MAX_STRUCT_SIZE */
  FUSE_ELEMENT_F64 = 0,  /* IEEE double */
  FUSE_ELEMENT_I64 = 1,  /* 64-bit signed integer (identifiers, not coupled values) */
  FUSE_MEMSPACE_HOST = 0,  /* pointer addressable by the host CPU */
  FUSE_MEMSPACE_DEVICE = 1,  /* pointer in the default device memory space of this build's Kokkos */
  FUSE_OWNERSHIP_OWNED = 0,  /* every entry owned by this process; the default */
  FUSE_OWNERSHIP_GHOSTED = 1,  /* owned entries first, then ghosts; the graph's ownership rule applies */
  FUSE_OWNERSHIP_REPLICATED = 2,  /* the whole field on every process */
  FUSE_CAP_DEVICE_FIELDS = 1,  /* FUSE_MEMSPACE_DEVICE accepted */
  FUSE_CAP_CHECKPOINT = 2,  /* requires_checkpoint/requires_restore are meaningful (implicit coupling groups) */
  FUSE_CAP_MPI = 4,  /* a communicator may be set; without it everything runs on one process */
  FUSE_CAP_MPI_CONNECT = 8,  /* coupling between separately launched executables over MPI connect/accept or MPMD */
  FUSE_CAP_LOWFIVE = 16,  /* coupling between executables through LowFive's in-memory HDF5 path */
  FUSE_CAP_YAML = 32,  /* load_graph accepts a YAML path */
  FUSE_ABI_VERSION = 1,  /* the table version this header describes */
  FUSE_ABI_MAX_STRUCT_SIZE = 65536  /* a struct_size above this is a corrupt header, not a future one */
};

/* Every entry point returns one of the FUSE_OK / FUSE_ERR_* values. */
typedef int32_t fuse_status;

/* ---- closed value types: no struct_size, and they never grow --------- */

/* An exact rational time. Time never crosses this boundary as a double:
 * the coupler's schedule is exact, and a caller that rounds loses the
 * agreement on where a step begins and ends. */
typedef struct fuse_exact_time {
  int64_t numerator;
  int64_t denominator;  /* > 0 */
} fuse_exact_time;

typedef struct fuse_semantic_version {
  uint32_t major;
  uint32_t minor;
  uint32_t patch;
} fuse_semantic_version;

/* An opaque coupling context; create() makes one, destroy() ends it. */
typedef struct fuse_ctx fuse_ctx;

/* ---- argument structs ------------------------------------------------- */
/* Every struct below begins with `uint32_t struct_size`, which the caller
 * sets to sizeof(the struct it was compiled against). Members are only ever
 * APPENDED; the callee reads those that struct_size says are present and
 * takes the documented default for the rest. A struct_size below the
 * oldest known layout, or above FUSE_ABI_MAX_STRUCT_SIZE, is
 * FUSE_ERR_VERSION. */

/* placeholder for an entry with no input or no output; callers pass NULL */
typedef struct fuse_null {
  uint32_t struct_size;  /* sizeof(fuse_null) */
} fuse_null;

/* what this library is */
typedef struct fuse_version_info {
  uint32_t              struct_size;
  fuse_semantic_version library;  /* semantic version of the library */
  uint32_t              abi_version;  /* highest table version fuse_coupler_abi() answers */
  uint32_t              reserved;  /* 0; fills the padding so that an appended member changes sizeof (abi-design.md rule 3) */
  const char*           string;  /* NUL-terminated, static storage, valid for the library's lifetime */
} fuse_version_info;

/* what this build can do; FUSE_CAP_* bits */
typedef struct fuse_capability_set {
  uint32_t struct_size;
  uint64_t flags;  /* OR of FUSE_CAP_* */
} fuse_capability_set;

/* a new context */
typedef struct fuse_context_out {
  uint32_t  struct_size;
  fuse_ctx* ctx;  /* owned by the caller until destroy */
} fuse_context_out;

/* the last error on a context (or thread-local when ctx is NULL); the caller */
/* owns the buffer */
typedef struct fuse_error {
  uint32_t    struct_size;
  int32_t     status;  /* out: the fuse_status of the failed call */
  int32_t     truncated;  /* out: 1 if the message did not fit */
  uint64_t    length;  /* out: full message length in bytes, excluding the NUL */
  char*       buffer;  /* in: caller's buffer, or NULL to query length only */
  uint64_t    capacity;  /* in: bytes available in buffer */
  const char* code;  /* out: the E-... code, static storage, valid until the next failing call */
} fuse_error;

/* where a coupling graph comes from; exactly one of yaml_path and bytes is set */
typedef struct fuse_graph_source {
  uint32_t    struct_size;
  const char* yaml_path;  /* NUL-terminated path, or NULL */
  const void* bytes;  /* canonical descriptor bytes (the frozen model), or NULL */
  uint64_t    byte_count;  /* length of bytes */
} fuse_graph_source;

/* where the loaded graph's canonical bytes are written */
typedef struct fuse_graph_sink {
  uint32_t struct_size;
  void*    buffer;  /* in: caller's buffer, or NULL to query the size */
  uint64_t capacity;  /* in: bytes available */
  uint64_t written;  /* out: bytes the graph needs; nothing is written when it exceeds capacity */
} fuse_graph_sink;

/* process-level settings, before initialize */
typedef struct fuse_setup_options {
  uint32_t        struct_size;
  int64_t         communicator;  /* Fortran handle of the communicator this process couples on (MPI_Comm_c2f), or 0 for none */
  int32_t         has_end_time;  /* 1 if end_time is set */
  int32_t         reserved;  /* must be 0 */
  fuse_exact_time end_time;  /* when is_coupling_ongoing turns false; the graph's own end otherwise */
} fuse_setup_options;

/* a field named in the graph */
typedef struct fuse_field_name {
  uint32_t    struct_size;
  const char* component;  /* NUL-terminated component name */
  const char* field;  /* NUL-terminated field name */
} fuse_field_name;

/* what the graph knows about a named field, resolved once at setup */
typedef struct fuse_field_ref {
  uint32_t struct_size;
  int32_t  handle;  /* pass to register_field; stable for the context's lifetime */
  int32_t  components;  /* values per entity the graph declares */
  int32_t  intent;  /* 0 export (Provides), 1 import (Requires), 2 both */
  int32_t  conservation;  /* 0 none, 1 intensive, 2 extensive */
} fuse_field_ref;

/* caller-owned storage bound to a field; the pointer must stay valid until */
/* destroy */
typedef struct fuse_field_view {
  uint32_t struct_size;
  int32_t  handle;  /* from field_handle */
  int32_t  element_type;  /* FUSE_ELEMENT_* */
  int32_t  memspace;  /* FUSE_MEMSPACE_* */
  int32_t  ownership;  /* FUSE_OWNERSHIP_* */
  int32_t  components;  /* values per entity; must equal fuse_field_ref.components */
  uint64_t count;  /* entities on this process (owned first when ghosted) */
  uint64_t owned_count;  /* owned entities; equals count unless ghosted */
  int64_t  stride;  /* elements between consecutive entities (1 = packed) */
  int64_t  component_stride;  /* elements between consecutive components of one entity (count*stride = structure-of-arrays, 1 = array-of-structures) */
  void*    data;  /* the storage */
} fuse_field_view;

/* which component is stepping */
typedef struct fuse_step_request {
  uint32_t    struct_size;
  const char* component;  /* NUL-terminated component name; must be one this process hosts */
} fuse_step_request;

/* what the coupler decided about this step; exact time, never a double */
typedef struct fuse_step_report {
  uint32_t        struct_size;
  int32_t         requires_checkpoint;  /* 1 if the component must save its state before advancing (begin_step) */
  int32_t         requires_restore;  /* 1 if the component must restore the state it saved and advance again (end_step) */
  int64_t         step;  /* step index within the run */
  int32_t         iteration;  /* sweep index inside an implicit coupling group; 0 outside */
  int32_t         reserved;  /* 0 */
  fuse_exact_time t_begin;  /* start of the step */
  fuse_exact_time t_end;  /* end of the step */
} fuse_step_report;

/* whether and where the coupling stands */
typedef struct fuse_ongoing {
  uint32_t        struct_size;
  int32_t         ongoing;  /* 1 while there is a step left to take */
  int64_t         period;  /* coupling period index */
  fuse_exact_time now;  /* the current coupling time */
} fuse_ongoing;

/* for an in-process driver: let the coupler run the loop */
typedef struct fuse_run_request {
  uint32_t struct_size;
  int64_t  periods;  /* how many coupling periods; -1 = until the end time */
} fuse_run_request;

